#!/bin/bash
set -euo pipefail
# Root-owned service wrapper. Drop all privileges before entering the sandbox.
if [ "$#" = 0 ]; then set -- /var/lib/liming-actions/runner/runsvc.sh; fi
exec /usr/bin/setpriv --reuid=actions-box --regid=actions-box --init-groups --no-new-privs --bounding-set=-all  /usr/bin/env -i HOME=/var/lib/liming-actions USER=actions-box LOGNAME=actions-box LANG=C.UTF-8  PATH=/opt/liming-runner-tools/node-v22.23.4-linux-x64/bin:/opt/hostedtoolcache/Python/3.12.16/x64/bin:/usr/bin:/bin  RUNNER_TOOL_CACHE=/opt/hostedtoolcache AGENT_TOOLSDIRECTORY=/opt/hostedtoolcache  XDG_CACHE_HOME=/var/lib/liming-actions/.cache  /usr/bin/bwrap --unshare-pid --new-session --die-with-parent --cap-drop ALL  --ro-bind /usr /usr --symlink usr/bin /bin --symlink usr/sbin /sbin  --symlink usr/lib /lib --symlink usr/lib64 /lib64  --ro-bind /etc/liming-actions/sandbox-etc /etc  --ro-bind /etc/ssl/certs /etc/ssl/certs --ro-bind /etc/fonts /etc/fonts \
 --ro-bind /etc/alternatives /etc/alternatives  --ro-bind /usr/share/fonts /usr/share/fonts  --ro-bind /opt/google /opt/google  --ro-bind /opt/liming-runner-tools /opt/liming-runner-tools  --bind /opt/hostedtoolcache /opt/hostedtoolcache  --bind /var/lib/liming-actions /var/lib/liming-actions  --proc /proc --dev /dev --tmpfs /tmp --tmpfs /run --tmpfs /home --tmpfs /workspace  --chdir /var/lib/liming-actions/runner "$@"
